const parsed = $input.first().json;
const config = $('Set: feed URL & Slack webhook').first().json;

const channel = parsed && parsed.rss && parsed.rss.channel;
if (!channel) {
  throw new Error('Extract feed items: could not find rss.channel in the parsed feed. This workflow expects a standard RSS 2.0 feed (see the Overview sticky note for the Atom limitation).');
}

const feedTitle = channel.title || 'Untitled feed';
const rawItems = Array.isArray(channel.item) ? channel.item : (channel.item ? [channel.item] : []);
const maxItems = Number.isFinite(config.maxItems) ? config.maxItems : 10;

const items = rawItems.slice(0, maxItems).map((item) => ({
  title: item.title || '(no title)',
  link: item.link || '',
  pubDate: item.pubDate || '',
  summary: item.description || ''
}));

if (items.length === 0) {
  throw new Error('Extract feed items: the feed was parsed but contained no <item> entries.');
}

return [{ json: { feedTitle, items, slackWebhookUrl: config.slackWebhookUrl } }];

const d = $input.first().json;

const systemPrompt = 'You write short, factual digests of RSS feed items. Only summarize what is actually present in the provided items — do not invent facts, dates, or details not present in the source data. If an item has no summary text, say so rather than guessing its content.';

const itemsText = d.items.map((it, i) => `${i + 1}. ${it.title}${it.pubDate ? ' (' + it.pubDate + ')' : ''}\n${it.summary || '(no summary provided)'}\n${it.link}`).join('\n\n');

const userPrompt = `Write a short digest (a few bullet points) of the latest items from "${d.feedTitle}". Use only the information below — do not add facts that aren't here.\n\n${itemsText}`;

return [{ json: { systemPrompt, userPrompt, slackWebhookUrl: d.slackWebhookUrl, feedTitle: d.feedTitle } }];

const resp = $input.first().json;
const promptCtx = $('Build Claude prompt').first().json;

const textBlock = (resp.content || []).find((b) => b.type === 'text');
const digest = (textBlock && textBlock.text) || '(no digest text returned)';

return [{
  json: {
    slackWebhookUrl: promptCtx.slackWebhookUrl,
    slackRequestBody: { text: `:newspaper: *${promptCtx.feedTitle} — digest*\n${digest}` }
  }
}];
